require(['N/piremoval'], function(piremoval) {
    function removePersonalInformation() {
        var piRemovalTask = piremoval.createTask({
            recordType: 'customer',
            recordIds: [11, 19],
            fieldIds: ['comments', 'phone'],
            workflowIds: [1],
            historyOnly: false,
